    %l2_norm = stablehlo.sqrt %sum_sq : tensor<3xf32>

    // Step 4: Broadcast l2_norm to shape <3x8>
    %l2_norm_bcast = stablehlo.broadcast_in_dim %l2_norm, dims = [0] : (tensor<3xf32>) -> tensor<3x8xf32>

